def pagina_sapatas():
    st.header("Assentamento de Sapatas")

    if st.session_state.get("option") != "Previsão de Geopressões":
        st.error('Função não disponível para "Retroanálise"', icon="🚨")
        return

    df_tvp = st.session_state.get("df_est", pd.DataFrame()).copy()
